import{_ as o,o as e,c as a,a2 as r}from"./chunks/framework.CqdVOxXJ.js";const s="/rakkii-cars-guide/screenshots/v2/a10b-qc-gate.png",k=JSON.parse('{"title":"5. QC and ready for pickup","description":"","frontmatter":{},"headers":[],"relativePath":"desk/job/05-qc-and-ready.md","filePath":"desk/job/05-qc-and-ready.md","lastUpdated":1794621279000}'),n={name:"desk/job/05-qc-and-ready.md"};function i(d,t,c,h,l,p){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_5-qc-and-ready-for-pickup" tabindex="-1">5. QC and ready for pickup <a class="header-anchor" href="#_5-qc-and-ready-for-pickup" aria-label="Permalink to &quot;5. QC and ready for pickup&quot;">​</a></h1><p><strong>Who:</strong> Technician, then owner or admin · <strong>Where:</strong> the job&#39;s <strong>Work</strong> tab · <strong>Status after:</strong> Ready for pickup</p><h2 id="what-the-technician-does" tabindex="-1">What the technician does <a class="header-anchor" href="#what-the-technician-does" aria-label="Permalink to &quot;What the technician does&quot;">​</a></h2><ol><li>Ticks the <strong>Bay checklist</strong>.</li><li>Presses <strong>Send to QC</strong> on the bay checklist card. The status becomes <strong>Quality check</strong>.</li><li>Takes the four QC photos: <strong>Front</strong>, <strong>Rear</strong>, <strong>Left side (LS)</strong>, <strong>Right side (RS)</strong>.</li></ol><p>The technician guide has the details: <a href="/rakkii-cars-guide/technician/">Your day in the bay</a>.</p><h2 id="what-you-do" tabindex="-1">What you do <a class="header-anchor" href="#what-you-do" aria-label="Permalink to &quot;What you do&quot;">​</a></h2><ol><li>Check the work and the photos (<strong>Show photos</strong> on the <strong>QC photos</strong> card).</li><li>Press <strong>Ready for pickup</strong> on the <strong>QC photos</strong> card.</li><li>Not right? Press <strong>Back to shop</strong> to send it back to the bay.</li></ol><p>Let the customer know the car is ready.</p><p><strong>Ready for pickup</strong> stays grey until all four photos are in. The progress card names the missing angles, for example &quot;Take the missing QC photos (Front, Rear, Left side (LS), Right side (RS)) before marking ready for pickup. 0 of 4 done.&quot;</p><p><img src="'+s+'" alt="QC photos card at 0/4: Ready for pickup is grey"></p><div class="warning custom-block"><p class="custom-block-title">No way to take the photos?</p><p>Only the owner or admin can skip them:</p><ol><li>Open the <strong>Release</strong> tab and expand <strong>Release without all QC photos</strong>.</li><li>Type a <strong>QC override reason</strong> and press <strong>Save QC override</strong>.</li><li><strong>Ready for pickup</strong> unlocks. The reason is saved on the job.</li></ol></div><p><strong>Next:</strong> <a href="/rakkii-cars-guide/desk/job/06-bill-and-collect">6. Bill and collect</a></p>',12)])])}const u=o(n,[["render",i]]);export{k as __pageData,u as default};
